/* Dạng B: dịch Việt → Trung */
tr:[
 {vi:"Cô ấy tìm trong túi mãi mà thế nào cũng không thấy.",g:"怎么都没……",a:["她在包里找了半天怎么都没找到","她在包里找了半天怎么也没找到","她在包里找了很长时间怎么都没找到","她在包里找了很久怎么都没找到"],r:["她在包里找了半天，怎么都没找到。","Tā zài bāo li zhǎole bàntiān, zěnme dōu méi zhǎodào."]},
 {vi:"Mùa hè sắp đến, trời ngày càng nóng.",g:"一天比一天",a:["夏天快到了天气一天比一天热","夏天快到了天气也一天比一天热","夏天快要到了天气一天比一天热","夏天要到了天气一天比一天热"],r:["夏天快到了，天气一天比一天热。","Xiàtiān kuài dào le, tiānqì yì tiān bǐ yì tiān rè."]},
 {vi:"Khoảng mười giờ rưỡi tối tôi mới về đến nhà.",g:"大约 / 左右",a:["我晚上大约十点半才到家","我晚上十点半左右才到家","晚上大约十点半我才到家","晚上十点半左右我才到家","我大约晚上十点半才到家"],r:["我晚上大约十点半才到家。","Wǒ wǎnshang dàyuē shí diǎn bàn cái dào jiā."]},
 {vi:"Là bạn thân, chúng tôi luôn giúp đỡ nhau.",g:"作为",a:["作为好朋友我们一直互相帮助","作为好朋友我们总是互相帮助","作为好朋友我们一直互相帮忙"],r:["作为好朋友，我们一直互相帮助。","Zuòwéi hǎo péngyou, wǒmen yìzhí hùxiāng bāngzhù."]},
 {vi:"Tết Trung thu là ngày cả nhà đoàn tụ.",g:"团圆",a:["中秋节是一家人团圆的日子","中秋节是家人团圆的日子","中秋节是全家团圆的日子"],r:["中秋节是一家人团圆的日子。","Zhōngqiūjié shì yì jiā rén tuányuán de rìzi."]}],
