n1:[
 ["那个叫东北虎，是国家一级保护动物。","那个叫东北虎，是国家一____保护动物。","级","ji","Nàge jiào Dōngběihǔ, shì guójiā yī ____ bǎohù dòngwù."],
 ["现在是节假日，人多。","现在是____，人多。","节假日","jiejiari","Xiànzài shì ____, rén duō."],
 ["这茶闻着真香！","这茶闻着真____！","香","xiang","Zhè chá wénzhe zhēn ____!"],
 ["中秋节和生日赶在了一块儿，真巧、真好！","中秋节和生日赶在了一块儿，真____、真好！","巧","qiao","Zhōngqiūjié hé shēngrì gǎn zàile yíkuàir, zhēn ____, zhēn hǎo!"],
 ["看到一桌子饭菜和突然出现的父母，他感觉特别幸福。","看到一桌子饭菜和突然____的父母，他感觉特别幸福。","出现","chuxian","Kàndào yì zhuōzi fàncài hé tūrán ____ de fùmǔ, tā gǎnjué tèbié xìngfú."],
 ["每当回忆起童年，我最美好的记忆很多也发生在过年时。","每当回忆起____，我最美好的记忆很多也发生在过年时。","童年","tongnian","Měi dāng huíyì qǐ ____, wǒ zuì měihǎo de jìyì hěn duō yě fāshēng zài guònián shí."]],
n2:[
 "我们想看那只熊猫，可是它怎么都不出来。",
 "夏天快到了，天气也一天比一天热。",
 "作为好朋友，我们一直互相关心、互相帮助。"],
d2:{ /* 选择合适的内容完成短文 (sách tr.35) */
 o:["兄弟姐妹都离开了家","很难见面","小时候喜欢过节","一家人聚在一起"],
 s:["冬冬从小到大都喜欢过节，特别是春节和元宵节。","，是因为可以吃到很多好吃的。长大后，","，去外地上大学、工作。平时大家很忙，","，但一到重要节日，在外地的兄弟姐妹就都回来了，和父母一起过节。","，特别热闹，也特别开心。"],
 a:[2,0,1,3],
 op:["Xiōngdì jiěmèi dōu líkāile jiā","Hěn nán jiànmiàn","Xiǎoshíhou xǐhuan guò jié","Yì jiā rén jù zài yìqǐ"],
 py:"Dōngdong cóng xiǎo dào dà dōu xǐhuan guò jié, tèbié shì Chūnjié hé Yuánxiāojié. (1) ____, shì yīnwèi kěyǐ chīdào hěn duō hǎochī de. Zhǎngdà hòu, (2) ____, qù wàidì shàng dàxué, gōngzuò. Píngshí dàjiā hěn máng, (3) ____, dàn yí dào zhòngyào jiérì, zài wàidì de xiōngdì jiěmèi jiù dōu huílai le, hé fùmǔ yìqǐ guò jié. (4) ____, tèbié rènao, yě tèbié kāixīn."},
/* ===== Nói ===== */
rp:[0,1],
roles:[["刘小明","王一雪","刘明"],["白家月","安妮","王一飞","杨同乐","陈天中"]],
retell:{t:2,steps:[["中秋节时中国人一般都……。但是有些人由于……，不能回家，只能一个人……过节。","Zhōngqiūjié shí Zhōngguórén yìbān dōu ……. Dànshì yǒuxiē rén yóuyú ……, bù néng huí jiā, zhǐ néng yí ge rén …… guò jié."],["周力就是……。他是……，今年中秋假期，要负责……。","Zhōu Lì jiù shì ……. Tā shì ……, jīnnián Zhōngqiū jiàqī, yào fùzé ……."],["周力的父母知道周力……后，就决定来一次……。","Zhōu Lì de fùmǔ zhīdào Zhōu Lì …… hòu, jiù juédìng lái yí cì ……."],["早上五点左右他们就……，大约七点就来到了……。","Zǎoshang wǔ diǎn zuǒyòu tāmen jiù ……, dàyuē qī diǎn jiù láidàole ……."],["在儿子家，他们做了一桌……，有……等等，还有……。周力下班回家，看到……，他感觉特别幸福。","Zài érzi jiā, tāmen zuòle yì zhuō ……, yǒu …… děngděng, hái yǒu ……. Zhōu Lì xiàbān huí jiā, kàndào ……, tā gǎnjué tèbié xìngfú."],["这个中秋节，地点……，但……。","Zhège Zhōngqiūjié, dìdiǎn ……, dàn ……."]],
 kw:[["中秋节","zhongqiujie"],["工作需要","gongzuoxuyao"],["之中","zhizhong"],["铁路","tielu"],["人员","renyuan"],["反向团圆","fanxiangtuanyuan"],["左右","zuoyou"],["大约","dayue"],["高铁","gaotie"],["烤肉","kaorou"],["西红柿","xihongshi"],["出现","chuxian"],["幸福","xingfu"]]},
talk:{title:"我最喜欢的节日",vi:"Giới thiệu ngày lễ em thích nhất: đó là ngày gì, mọi người làm gì, ăn gì, vì sao em thích. Nói khoảng 1 phút.",
 out:[["我最喜欢的节日是……","Ngày lễ em thích nhất"],["作为……，……对我们来说有着……的意义","Ý nghĩa của ngày lễ"],["……到来时，人们会……","Mọi người làm gì, ăn gì"],["每当回忆起……，我……","Một kỷ niệm của em"]],
 req:[["作为",[["作为","zuowei"]]],["大约 / 左右",[["大约","dayue"]],[["左右","zuoyou"]]],["一……比一……",[["比一","biyi"]]],["怎么都 / 也 + 不 / 没",[["怎么都","zenmedou"]],[["怎么也","zenmeye"]]],["传统 / 意义 / 团圆 / 美食",[["传统","chuantong"]],[["意义","yiyi"]],[["团圆","tuanyuan"]],[["美食","meishi"]]]],
 m:["我最喜欢的节日是越南的春节。作为越南最重要的传统节日，春节对我们来说有着特别的意义，是一家人团圆的日子。春节到来时，不管在哪儿工作，大家都想回家过年。春节前，我们要打扫卫生，还要准备各种美食，最有名的是“bánh chưng”。除夕晚上，一家人一边吃年夜饭，一边聊天儿，大约十二点，大家互相祝新年快乐。这几年，我们家过年一年比一年热闹。每当回忆起童年，我最美好的记忆也都发生在过年时。小时候，我和哥哥大年初一早上六点左右就起床，穿上新衣服去给爷爷奶奶拜年。那种幸福的感觉，我怎么也忘不了。",
    "Wǒ zuì xǐhuan de jiérì shì Yuènán de Chūnjié. Zuòwéi Yuènán zuì zhòngyào de chuántǒng jiérì, Chūnjié duì wǒmen lái shuō yǒuzhe tèbié de yìyì, shì yì jiā rén tuányuán de rìzi. Chūnjié dàolái shí, bùguǎn zài nǎr gōngzuò, dàjiā dōu xiǎng huí jiā guònián. Chūnjié qián, wǒmen yào dǎsǎo wèishēng, hái yào zhǔnbèi gèzhǒng měishí, zuì yǒumíng de shì “bánh chưng”. Chúxī wǎnshang, yì jiā rén yìbiān chī niányèfàn, yìbiān liáotiānr, dàyuē shí'èr diǎn, dàjiā hùxiāng zhù xīnnián kuàilè. Zhè jǐ nián, wǒmen jiā guònián yì nián bǐ yì nián rènao. Měi dāng huíyì qǐ tóngnián, wǒ zuì měihǎo de jìyì yě dōu fāshēng zài guònián shí. Xiǎoshíhou, wǒ hé gēge dànián chūyī zǎoshang liù diǎn zuǒyòu jiù qǐchuáng, chuānshang xīn yīfu qù gěi yéye nǎinai bàinián. Nà zhǒng xìngfú de gǎnjué, wǒ zěnme yě wàng bu liǎo.",
    "Ngày lễ em thích nhất là Tết Nguyên đán của Việt Nam. Là ngày lễ truyền thống quan trọng nhất của Việt Nam, Tết có ý nghĩa đặc biệt với chúng em, là ngày cả nhà đoàn tụ. Khi Tết đến, dù làm việc ở đâu, mọi người đều muốn về nhà ăn Tết. Trước Tết, chúng em phải dọn dẹp nhà cửa, còn chuẩn bị đủ loại món ngon, nổi tiếng nhất là bánh chưng. Đêm giao thừa, cả nhà vừa ăn cơm tất niên vừa trò chuyện, khoảng mười hai giờ, mọi người chúc nhau năm mới vui vẻ. Mấy năm nay, nhà em ăn Tết năm sau vui hơn năm trước. Mỗi khi nhớ lại tuổi thơ, những ký ức đẹp nhất của em cũng đều diễn ra vào dịp Tết. Hồi nhỏ, sáng mùng một em và anh trai dậy khoảng sáu giờ, mặc quần áo mới đi chúc Tết ông bà. Cảm giác hạnh phúc ấy, em thế nào cũng không quên được."]},
/* ===== Viết ===== */
vtNote:"Phần này luyện mục tiêu 2: <b>viết</b> về đặc điểm và hoạt động của ngày lễ Tết.",
