var APY=Object.assign(window.APY||{},{"你的国家有哪些重要节日？这些节日到来时人们会吃什么美食？":"Nǐ de guójiā yǒu nǎxiē zhòngyào jiérì? Zhèxiē jiérì dàolái shí rénmen huì chī shénme měishí?","你和兄弟姐妹或者好朋友节假日在一起时都会做些什么？":"Nǐ hé xiōngdì jiěmèi huòzhě hǎo péngyou jiéjiàrì zài yìqǐ shí dōu huì zuò xiē shénme?","节假日的时候，我和哥哥常常一起回老家看爷爷奶奶，有时候也和好朋友一起去看电影、吃好吃的。":"Jiéjiàrì de shíhou, wǒ hé gēge chángcháng yìqǐ huí lǎojiā kàn yéye nǎinai, yǒu shíhou yě hé hǎo péngyou yìqǐ qù kàn diànyǐng, chī hǎochī de.","仍然":"réngrán","已":"yǐ","香":"xiāng","之中":"zhīzhōng","有着":"yǒuzhe","出现":"chūxiàn","到来":"dàolái","老虎":"lǎohǔ","喊":"hǎn","回忆":"huíyì","千万":"qiānwàn","巧":"qiǎo","景区":"jǐngqū","演出":"yǎnchū","传统":"chuántǒng","团圆":"tuányuán","意义":"yìyì","开玩笑":"kāi wánxiào","美食":"měishí","童年":"tóngnián","大约":"dàyuē","作为":"zuòwéi","六一儿童节，刘明、王一雪带刘小明到北京野生动物园看动物，他们先坐车进入猛兽区。":"Liù-Yī Értóngjié, Liú Míng, Wáng Yīxuě dài Liú Xiǎomíng dào Běijīng Yěshēng Dòngwùyuán kàn dòngwù, tāmen xiān zuò chē jìnrù měngshòu qū.","王一雪提醒小明：":"Wáng Yīxuě tíxǐng Xiǎomíng:","别害怕":"bié hàipà","不要吃东西":"búyào chī dōngxi","看看熊和老虎":"kànkan xióng hé lǎohǔ","不要总是大喊":"búyào zǒngshì dà hǎn","刘明觉得景区怎么样？":"Liú Míng juéde jǐngqū zěnmeyàng?","游客很多":"yóukè hěn duō","门票便宜":"ménpiào piányi","又大又美":"yòu dà yòu měi","饭馆很多":"fànguǎn hěn duō","在王一飞家，王一飞夫妇邀请白家月、安妮和陈天中过中秋节。":"Zài Wáng Yīfēi jiā, Wáng Yīfēi fūfù yāoqǐng Bái Jiāyuè, Ānní hé Chén Tiānzhōng guò Zhōngqiūjié.","王一飞和杨同乐准备了什么？":"Wáng Yīfēi hé Yáng Tónglè zhǔnbèile shénme?","月饼、葡萄和苹果":"yuèbing, pútao hé píngguǒ","葡萄、西瓜和苹果":"pútao, xīguā hé píngguǒ","月饼、苹果、西瓜和茶":"yuèbing, píngguǒ, xīguā hé chá","月饼、葡萄、西瓜和茶":"yuèbing, pútao, xīguā hé chá","李文为什么没来？":"Lǐ Wén wèishénme méi lái?","在学校学习":"zài xuéxiào xuéxí","去买水果了":"qù mǎi shuǐguǒ le","要给爷爷过生日":"yào gěi yéye guò shēngrì","和同事一起过节":"hé tóngshì yìqǐ guò jié","中秋节的“反向团圆”":"Zhōngqiūjié de “fǎnxiàng tuányuán”","周力不能回家过中秋节，是因为：":"Zhōu Lì bù néng huí jiā guò Zhōngqiūjié, shì yīnwèi:","不想回家":"bù xiǎng huí jiā","工作需要":"gōngzuò xūyào","没买到车票":"méi mǎidào chēpiào","想去外地过节":"xiǎng qù wàidì guò jié","中秋节这天，周力的父母为儿子做了什么？":"Zhōngqiūjié zhè tiān, Zhōu Lì de fùmǔ wèi érzi zuòle shénme?","买月饼":"mǎi yuèbing","打扫卫生":"dǎsǎo wèishēng","买了一件上衣":"mǎile yí jiàn shàngyī","做了一桌饭菜":"zuòle yì zhuō fàncài","节日的美好记忆":"Jiérì de měihǎo jìyì","下列哪个节日没有提到？":"Xiàliè nǎge jiérì méiyǒu tídào?","春节":"Chūnjié","元宵节":"Yuánxiāojié","端午节":"Duānwǔjié","六一儿童节":"Liù-Yī Értóngjié","根据课文，春节到来时，人们会做什么？":"Gēnjù kèwén, Chūnjié dàolái shí, rénmen huì zuò shénme?","准备美食":"zhǔnbèi měishí","外出看花":"wàichū kàn huā","出去旅游":"chūqu lǚyóu","照顾孩子":"zhàogù háizi","怎么":"zěnme","也":"yě","没想到":"méi xiǎngdào","这么大":"zhème dà","中秋节":"Zhōngqiūjié","热闹":"rènao","比一年":"bǐ yì nián","一年":"yì nián","这几年":"zhè jǐ nián","高铁":"gāotiě","早上五点":"zǎoshang wǔ diǎn","就坐上了":"jiù zuòshangle","左右":"zuǒyòu","特别的意义":"tèbié de yìyì","传统节日":"chuántǒng jiérì","跑丢了":"pǎodiū le","小明":"Xiǎomíng","别":"bié","一会儿":"yíhuìr","怎么都没……":"zěnme dōu méi……","一天比一天":"yì tiān bǐ yì tiān","大约/左右":"dàyuē / zuǒyòu","怎么都/也+不/没":"zěnme dōu / yě + bù / méi","爸爸、妈妈，快看，熊和老虎都在这儿呢！":"Bàba, māma, kuài kàn, xióng hé lǎohǔ dōu zài zhèr ne!","你们看，那个叫东北虎，是国家一级保护动物。那边树林里还有很多动物呢。":"Nǐmen kàn, nàge jiào Dōngběihǔ, shì guójiā yī jí bǎohù dòngwù. Nàbiān shùlín li hái yǒu hěn duō dòngwù ne.","咱们都能看到吧？":"Zánmen dōu néng kàndào ba?","真不错，这景区真大、真美！我知道北京野生动物园很大，可怎么也没想到这么大！":"Zhēn búcuò, zhè jǐngqū zhēn dà, zhēn měi! Wǒ zhīdào Běijīng Yěshēng Dòngwùyuán hěn dà, kě zěnme yě méi xiǎngdào zhème dà!","来，大家快吃月饼，这儿还有葡萄、西瓜。":"Lái, dàjiā kuài chī yuèbing, zhèr hái yǒu pútao, xīguā.","这是今年的新茶，你们也尝尝。":"Zhè shì jīnnián de xīn chá, nǐmen yě chángchang.","好的。这茶闻着真香！":"Hǎo de. Zhè chá wénzhe zhēn xiāng!","我还是第一次在中国过中秋节呢。":"Wǒ hái shì dì-yī cì zài Zhōngguó guò Zhōngqiūjié ne.","在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。对了，家月，今天是李文爷爷的生日，李文来不了了，你就多吃一块月饼吧。":"Zài Zhōngguó, měi nián Zhōngqiūjié dōu huì jǔbàn hěn duō huódòng, érqiě zhè jǐ nián yì nián bǐ yì nián rènao. Duì le, Jiāyuè, jīntiān shì Lǐ Wén yéye de shēngrì, Lǐ Wén lái bu liǎo le, nǐ jiù duō chī yí kuài yuèbing ba.","谢谢，那我就不客气了。":"Xièxie, nà wǒ jiù bú kèqi le.","中秋节和生日赶在了一块儿，真巧、真好！中秋节多陪陪家人也是应该的。":"Zhōngqiūjié hé shēngrì gǎn zàile yíkuàir, zhēn qiǎo, zhēn hǎo! Zhōngqiūjié duō péipei jiārén yě shì yīnggāi de.","我最喜欢的节日":"wǒ zuì xǐhuan de jiérì","我最喜欢的节日是……":"Wǒ zuì xǐhuan de jiérì shì ……","作为……，……对我们来说有着……的意义":"zuòwéi……, …… duì wǒmen lái shuō yǒuzhe…… de yìyì","……到来时，人们会……":"…… dàolái shí, rénmen huì……","每当回忆起……，我……":"měi dāng huíyì qǐ……, wǒ……","小明，注意安全，不要一直大喊！":"Xiǎomíng, zhùyì ānquán, búyào yìzhí dà hǎn!","对。景区的车每到一个动物区都会停一会儿，让人们能近距离看看这些动物。":"Duì. Jǐngqū de chē měi dào yí ge dòngwù qū dōu huì tíng yíhuìr, ràng rénmen néng jìn jùlí kànkan zhèxiē dòngwù.","这里有几千只动物呢，能不大吗？现在是节假日，人多。小明，一会儿千万别跑丢了，我可不是开玩笑呢。":"Zhèlǐ yǒu jǐ qiān zhī dòngwù ne, néng bú dà ma? Xiànzài shì jiéjiàrì, rén duō. Xiǎomíng, yíhuìr qiānwàn bié pǎodiū le, wǒ kě bú shì kāi wánxiào ne.","我在加拿大时和中国朋友一起过过中秋节。我记得那天，外面的街道、剧院有很多演出活动。":"Wǒ zài Jiānádà shí hé Zhōngguó péngyou yìqǐ guò guo Zhōngqiūjié. Wǒ jìde nà tiān, wàimiàn de jiēdào, jùyuàn yǒu hěn duō yǎnchū huódòng.","你最喜欢什么节日？":"Nǐ zuì xǐhuan shénme jiérì?","为什么喜欢？":"Wèishénme xǐhuan?","过节时你都会做什么？":"Guò jié shí nǐ dōu huì zuò shénme?","一年比一年":"yì nián bǐ yì nián","怎么也忘不了":"zěnme yě wàng bu liǎo","我最喜欢过的节日":"wǒ zuì xǐhuan guò de jiérì","一……比一……":"yī…… bǐ yī……","能够听懂并交流节日生活方面的话题。":"Nénggòu tīngdǒng bìng jiāoliú jiérì shēnghuó fāngmiàn de huàtí.","能够口头或书面表达节日特点、节日活动等内容。":"Nénggòu kǒutóu huò shūmiàn biǎodá jiérì tèdiǎn, jiérì huódòng děng nèiróng.","了解中国人特别重视传统节日背后的文化内涵。":"Liǎojiě Zhōngguórén tèbié zhòngshì chuántǒng jiérì bèihòu de wénhuà nèihán."});
